L["EM_HELP_BTN"] = "? Aiuto"
L["EM_HELP_BTN_TIP"] = "Apre la configurazione guidata completa di MSUF\nal capitolo Modalità modifica."
L["EM_HELP_CDM"] = "|cff60a5ffCDM|r alterna l'ancora globale di Essential Cooldown Manager. |cff60a5ffAnchor|r apre il selettore ancoraggio; passa su un frame con nome, tieni Ctrl e clicca sinistro per usarlo come ancora globale. Scegliere un'ancora personalizzata disattiva CDM."
L["EM_HELP_COPYTO"] = "Nei popup di unità e castbar, |cff60a5ffCopy To|r copia le impostazioni del popup attuale su un altro bersaglio. La copia dei frame unità mantiene posizione e ancora del bersaglio; la copia delle castbar mantiene gli offset X/Y del bersaglio."
L["EM_HELP_DRAG"] = "Tieni premuto il tasto sinistro del mouse su un overlay mover e trascinalo. Il frame reale segue il mover e la lettura X/Y sotto l'overlay mostra l'offset attuale sullo schermo. Rilascia per salvare la posizione."
L["EM_HELP_EXIT"] = "|cff60a5ffExit|r esce dalla modalità modifica e conserva le modifiche attuali. Anche entrare in combattimento esce dalla modalità modifica. Esc chiude o annulla il popup; il pulsante Exit dell'HUD è il modo normale per uscire."
L["EM_HELP_NUDGE"] = "Le frecce muovono il bersaglio attivo. Priorità: maniglia anteprima selezionata, popup castbar aperto, popup aura aperto, poi il frame unità selezionato. Passo: 1 px, Maiusc = 5 px, Ctrl = 10 px, Alt = passo griglia attuale."
L["EM_HELP_OPACITY"] = "Scorri sul controllo |cff60a5ffBG ##%|r per cambiare solo l'opacità dello sfondo della modalità modifica. Non cambia l'alfa del frame unità né la visibilità salvata."
L["EM_HELP_POPUP"] = "Clic sinistro su un mover senza trascinare apre il suo popup di modifica. I popup unità modificano dimensione, posizione, ancore testo, impostazioni di potere separato e opzioni copia-a-unità. I mover di castbar e aura aprono popup dedicati."
L["EM_HELP_PREVIEW"] = "|cff60a5ffPreview|r alterna dati segnaposto per bersaglio, focus, bersaglio del bersaglio, famiglio, boss e anteprime castbar mancanti mentre la modalità modifica è attiva. |cff60a5ffAuras|r alterna icone anteprima aura e box mover aura."
L["EM_HELP_SNAP"] = "La griglia è una guida visiva. Clic sinistro su |cff60a5ffGrid ##px|r attiva o disattiva le linee; lo scorrimento cambia la distanza. |cff60a5ffSnap|r è separato: se attivo, i mover trascinati si agganciano al centro dello schermo o a bordi/centri di altri mover visibili, con guide arancioni."
L["EM_HELP_TITLE"] = "Modalità modifica - Riferimento rapido"
L["EM_HELP_UNDO"] = "|cff60a5ffUndo|r e |cff60a5ffRedo|r ripristinano modifiche recenti della modalità modifica catturate prima di trascinamenti, spostamenti e modifiche popup. |cff60a5ffCancel All|r chiede conferma, ripristina lo snapshot precedente all'ingresso in modalità modifica e poi esce."
