L["No manual pins yet. While grouped, hover an MSUF Party, Raid, or Priority frame, then press your hotkey."] = "Nessun fissaggio manuale. In gruppo, passa su un riquadro MSUF di gruppo, incursione o prioritario e premi il tasto."
L["Use the hover hotkey above to add or remove players."] = "Usa il tasto al passaggio qui sopra per aggiungere o rimuovere giocatori."
