L["Skip all %d and continue"] = "Salta tutto %d e continua"
L["Skipping closes this release tour only. Every setting remains available in Menu2."] = "Saltando si chiude solo questo tour di rilascio. Ogni impostazione rimane disponibile nel Menu2."
L["Custom Aura tracking on Unitframes"] = "Tracciamento personalizzato dell'aura su Unitframes"
L["Build up to three frame-specific Custom lanes on Player, Target, Focus and Boss, then whitelist exact buff or debuff SpellIDs."] = "Costruisci fino a tre corsie personalizzate specifiche del frame su Giocatore, Bersaglio, Focus e Boss, quindi inserisci nella whitelist gli SpellID di buff o debuff esatti."
L["Your MSUF frames can act as focused WeakAura-style trackers with icons, timers, duration bars and full-frame tint, border, glow or pulse effects."] = "I tuoi fotogrammi MSUF possono agire come tracker focalizzati in stile WeakAura con icone, timer, barre di durata ed effetti di tinta, bordo, bagliore o impulso a pieno formato."
L["three Custom Aura trackers per supported Unitframe, exact spell whitelists and full-frame effects"] = "tre tracker Aura personalizzati per Unitframe supportato, liste bianche esatte di incantesimi ed effetti full-frame"
L["Build a Custom tracker"] = "Costruisci un tracker personalizzato"
L["Auras3: a full Aura menu rework"] = "Auras3: una rielaborazione completa del menu Aura"
L["The 5.71 Auras2 page has been rebuilt as Auras3, with separate Unitframe and Group workspaces plus Buff, Debuff and Custom lanes."] = "La pagina 5.71 Auras2 è stata ricostruita come Auras3, con aree di lavoro Unitframe e Gruppo separate più corsie Buff, Debuff e Personalizzate."
L["Each lane gets its own live preview, layout, growth, sorting, filters, blacklist or whitelist, cooldown text, swipe, stacks and duration bars."] = "Ogni corsia ottiene la propria anteprima dal vivo, layout, crescita, ordinamento, filtri, lista nera o lista bianca, testo di ricarica, scorrimento, pile e barre di durata."
L["the rebuilt Auras3 workspace, lane-specific previews, layouts, sorting, filters and styling"] = "l'area di lavoro Auras3 ricostruita, anteprime specifiche della corsia, layout, ordinamento, filtri e stile"
L["Explore the Aura rework"] = "Esplora la rielaborazione dell'Aura"
L["Adaptive Party and Raid layouts"] = "Layout adattivi per Party e Raid"
L["Group frames gained smarter layouts, stronger status handling, range behavior and clearer health feedback."] = "I frame di gruppo hanno ottenuto layout più intelligenti, una gestione dello stato più efficace, un comportamento a distanza e un feedback sulla salute più chiaro."
L["You can make one group setup adapt more cleanly between party, raid and encounter needs."] = "Puoi fare in modo che la configurazione di un gruppo si adatti in modo più pulito alle esigenze del gruppo, del raid e dell'incontro."
L["adaptive group layouts, range behavior and group status controls"] = "layout di gruppo adattivi, comportamento della gamma e controlli dello stato del gruppo"
L["Open Group Layout"] = "Apri il layout del gruppo"
L["New health values and text formats"] = "Nuovi valori di salute e formati di testo"
L["Health text can show abbreviated or full values with more consistent formatting across unit and group frames."] = "Il testo sanitario può mostrare valori abbreviati o completi con una formattazione più coerente tra i riquadri di unità e gruppo."
L["You can choose compact readability or exact numbers without giving up the layout you already use."] = "Puoi scegliere la leggibilità compatta o i numeri esatti senza rinunciare al layout che già utilizzi."
L["the new health abbreviations, full values and text-format options"] = "le nuove abbreviazioni sanitarie, i valori completi e le opzioni di formato testo"
L["Review Group Bars"] = "Revisione delle barre dei gruppi"
L["More flexible class resources"] = "Risorse di classe più flessibili"
L["Class resources gained detached layouts, additional shapes and finer per-slot and full-state colors."] = "Le risorse di classe hanno ottenuto layout separati, forme aggiuntive e colori più fini per slot e a stato completo."
L["You can move class information where your eyes already are and make important states easier to read."] = "Puoi spostare le informazioni sulla classe dove sono già i tuoi occhi e rendere più facile la lettura degli stati importanti."
L["detached class resources, new shapes and per-state colors"] = "risorse di classe indipendenti, nuove forme e colori per stato"
L["Configure Class Resources"] = "Configura le risorse della classe"
L["Cast target text"] = "Trasmetti il testo di destinazione"
L["Target, Focus and Boss cast bars can now show who the current spell is targeting, with dedicated text styling."] = "Le barre di lancio Bersaglio, Concentrazione e Boss ora possono mostrare chi sta prendendo di mira l'incantesimo corrente, con uno stile di testo dedicato."
L["You can identify the destination of an important cast without shifting attention away from the cast bar."] = "Puoi identificare la destinazione di un cast importante senza spostare l'attenzione dalla barra del cast."
L["cast-target names and their text styling on Target, Focus and Boss frames"] = "nomi dei bersagli di lancio e il loro stile di testo sui riquadri Target, Focus e Boss"
