L["Review your guided setup"] = "Rivedi la tua configurazione guidata"
L["Skipping this personal step uses neutral guidance and leaves navigation, Search, autosave, Undo/Redo and page reset unexplained."] = "Saltare questo passaggio personale utilizza una guida neutra e lascia inspiegabili la navigazione, la ricerca, il salvataggio automatico, l'annullamento/Redo e il ripristino della pagina."
L["Skipping frame placement leaves whole-frame movement, snapping, nudging and safe exit behavior unexplained."] = "Saltare il posizionamento del fotogramma lascia inspiegabili il movimento dell'intero fotogramma, lo scatto, gli spostamenti e il comportamento di uscita sicura."
L["Skipping the Player frame leaves its layout, text, indicators and aura options unreviewed."] = "Se si salta il riquadro del Lettore, il layout, il testo, gli indicatori e le opzioni dell'aura non vengono rivisti."
L["Skipping the Target frame leaves its layout, text, indicators and aura options unreviewed."] = "Se si salta il riquadro di destinazione, il layout, il testo, gli indicatori e le opzioni dell'aura non verranno rivisti."
L["Skipping the Focus frame leaves its layout, text, indicators and aura options unreviewed."] = "Se si salta il riquadro Focus, il layout, il testo, gli indicatori e le opzioni dell'aura non verranno rivisti."
L["Skipping the Pet frame leaves its layout, text, indicators and aura options unreviewed."] = "Se si salta la cornice dell'animale domestico, il layout, il testo, gli indicatori e le opzioni dell'aura non verranno rivisti."
L["Skipping Target of target leaves its layout, text and visibility options unreviewed."] = "Se si salta il target del target, il layout, il testo e le opzioni di visibilità non vengono revisionati."
L["Skipping Focus target leaves its layout, text and visibility options unreviewed."] = "Se si salta il target Focus, le opzioni di layout, testo e visibilità non vengono riviste."
L["Skipping Boss frames leaves their shared layout, text, indicators and aura options unreviewed."] = "Saltare i fotogrammi del Boss lascia non revisionati il layout condiviso, il testo, gli indicatori e le opzioni dell'aura."
L["Skipping group layout leaves frame size, growth, sorting, scaling and anchoring unreviewed."] = "Saltare il layout del gruppo lascia la dimensione del fotogramma, la crescita, l'ordinamento, il ridimensionamento e l'ancoraggio senza revisione."
L["Skipping group bars leaves health, power, text, range and dispel presentation unreviewed."] = "Saltare le barre di gruppo lascia senza revisione la presentazione di salute, potenza, testo, portata e dissolvenza."
L["Skipping group auras leaves group buff, debuff and spell-indicator behavior unreviewed."] = "Saltare le aure di gruppo lascia senza revisione il comportamento dei buff, dei debuff e degli indicatori di incantesimo del gruppo."
L["Skipping Bars leaves global textures, absorbs, outlines, highlights and power behavior unreviewed."] = "Saltare le battute lascia le texture globali, gli assorbimenti, i contorni, le luci e il comportamento di potenza senza revisione."
L["Skipping Cast Bars leaves cast appearance, text, empowered casts and interrupt cues unreviewed."] = "Saltare le barre di cast lascia l'aspetto del cast, il testo, i lanci potenziati e i segnali di interruzione non revisionati."
L["Skipping Colors leaves frame, power, aura, class, text and castbar colors unreviewed."] = "Se si saltano i colori, i colori di frame, potere, aura, classe, testo e barra di cast non vengono controllati."
L["Skipping Fonts leaves the global font, text styling, colors and name shortening unreviewed."] = "Se si saltano i caratteri, il carattere globale, lo stile del testo, i colori e l'abbreviazione dei nomi non vengono revisionati."
L["Skipping Aura styling leaves buff/debuff size, cooldown, stacks, duration bars and ordering unreviewed."] = "Se si salta lo stile dell'Aura, la dimensione del buff/debuff, il tempo di recupero, gli accumuli, le barre della durata e l'ordine non vengono revisionati."
L["Skipping Miscellaneous leaves language, menu behavior, startup, tooltips and Blizzard-frame integration unreviewed."] = "Se si salta Varie, la lingua, il comportamento dei menu, l'avvio, i suggerimenti e l'integrazione dei frame Blizzard non vengono controllati."
L["Skipping Class Resources leaves class layout, behavior, style, visibility and alternative power displays unreviewed."] = "Saltare le risorse della classe lascia senza revisione la disposizione, il comportamento, lo stile, la visibilità e le visualizzazioni dei poteri alternativi della classe."
L["Skipping Gameplay leaves combat timers, state behavior, class toggles and the combat crosshair unreviewed."] = "Saltare il gameplay lascia i timer di combattimento, il comportamento dello stato, i cambi di classe e il mirino di combattimento senza revisione."
L["Skipping Profiles leaves profile management, specialization assignment and export/import backup unreviewed."] = "Se si saltano i profili, la gestione dei profili, l'assegnazione delle specializzazioni e il backup dell'esportazione/import non vengono revisionati."
L["Skipping the final review hides the summary, but does not change any setting."] = "Saltare la revisione finale nasconde il riepilogo, ma non modifica alcuna impostazione."
