L["Drag = inner position · gear/double-click = options · right-click = actions · Ctrl-wheel/drag = zoom/pan · Edit Mode = whole frame"] = "Trascina = posizione interna · ingranaggio/double-click = opzioni · clic destro = azioni · Ctrl-ruota/drag = zoom/pan · Modalità modifica = intero fotogramma"
