L["Open Colors > Bar Gradient Colors for separate Health and Power gradient colors in the selected Bars scope."] = "Apri Colori > Colori sfumatura barra per colori sfumati di salute e potenza separati nell'ambito delle barre selezionato."
L["Open Colors > Group Frame Colors for shared Party, Raid and Mythic Raid colors."] = "Apri Colori > Raggruppa colori cornice per i colori Party, Raid e Raid Mitico condivisi."
L["Open Edit Mode and move Party Frames"] = "Apri la modalità Modifica e sposta i frame del party"
L["Open Group Frames > Auras for Buff/Debuff filters, lists, visibility, and layout. For text, cooldowns, stacks, and duration bars use Appearance > Auras and select Party or Raid scope."] = "Apri Frame di gruppo > Aure per filtri Buff/Debuff, elenchi, visibilità e layout. Per testo, tempi di recupero, accumuli e barre della durata, usa Aspetto > Aure e seleziona Ambito Party o Raid."
L["Open Group Frames > Layout. Text, Resource Bar, and Range Fade are arranged beside Frame Basics and Transparency. Dispel Overlay and Debuff Stripe are on the Dispel Overlay page. Heal prediction is in Global Style > Bars > Absorb Display."] = "Open Group Frames > Layout. Testo, Barra delle risorse e Dissolvenza intervallo sono disposti accanto a Nozioni di base sulla cornice e Trasparenza. Dispel Overlay e Debuff Stripe si trovano nella pagina Dispel Overlay. La previsione della guarigione è in Stile globale > Barre > Assorbi visualizzazione."
L["Open it and choose a different value."] = "Aprilo e scegli un valore diverso."
L["Open the affected UnitFrame > Auras > Debuffs and enable the native Dispellable rule. For Party/Raid use Group Frames > Auras > Debuffs."] = "Apri l'UnitFrame interessato > Aure > Debuff e abilita la regola nativa Dispellable. Per Party/Raid usa i frame di gruppo > Aure > Debuff."
L["Open the affected UnitFrame > Auras > Debuffs and use its frame-specific SpellID blacklist. Group exclusions live directly in Group Frames > Auras > Debuffs."] = "Apri l'UnitFrame interessato > Aure > Debuff e utilizza la lista nera SpellID specifica del frame. Le esclusioni di gruppo si trovano direttamente in Frame di gruppo > Aure > Debuff."
L["Open the affected UnitFrame > Auras and choose Buffs or Debuffs. Check its frame-specific Blizzard filters, blacklist, enabled state, and icon cap. For Party/Raid use Group Frames > Auras."] = "Apri l'UnitFrame interessato > Aure e scegli Buff o Debuff. Check its frame-specific Blizzard filters, blacklist, enabled state, and icon cap. Per Party/Raid usa Group Frames > Aures."
L["Open the affected UnitFrame > Auras for visibility, layout, filters, and blacklists. Use Appearance > Auras for scope-aware cooldown, stack, duration-bar, and icon styling."] = "Apri lo UnitFrame interessato > Aure per visibilità, layout, filtri e liste nere. Usa Aspetto > Aure per il tempo di recupero, lo stack, la barra della durata e lo stile delle icone in base all'ambito."
L["Open the frame and expand Auras. Buffs and Debuffs contain their own Blizzard filters and blacklists; Custom 1-3 contains its own whitelist. There is no separate Filter tab."] = "Apri la cornice ed espandi le Aure. Buff e Debuff contengono i propri filtri Blizzard e liste nere; Personalizzato 1-3 contiene la propria whitelist. Non esiste una scheda Filtro separata."
L["Open the matching color section below."] = "Open the matching color section below."
L["Opens Buff styling for this frame. Spell choice, placement, size, layer, and frame highlight stay unique to this indicator."] = "Apre lo stile Buff per questo frame. La scelta dell'incantesimo, il posizionamento, la dimensione, il livello e l'evidenziazione della cornice rimangono esclusivi per questo indicatore."
