L["Two arrows point to a movable frame. Drag it once; Next unlocks after a real position change."] = "Due frecce indicano una cornice mobile. Trascinalo una volta; Successivamente si sblocca dopo un reale cambio di posizione."
L["Type a new value, then press Enter."] = "Digitare un nuovo valore, quindi premere Invio."
L["UNLOCK, THEN CHANGE IT - Enable Corner Indicators, choose a slot, then select Custom Spell when requested."] = "SBLOCCA, POI CAMBIA - Abilita gli indicatori d'angolo, scegli uno slot, quindi seleziona Incantesimo personalizzato quando richiesto."
L["UNLOCK, THEN CHANGE IT - Enable Spell Indicators, choose a spec, then press a tracked spell tile."] = "SBLOCCA, POI CAMBIA - Abilita gli indicatori degli incantesimi, scegli una specializzazione, quindi premi il riquadro di un incantesimo tracciato."
L["UNLOCK, THEN CHANGE IT - Enable Spell Indicators, choose a spell, then select a Frame Effect."] = "SBLOCCA, POI CAMBIA - Abilita gli indicatori degli incantesimi, scegli un incantesimo, quindi seleziona un effetto cornice."
L["UNLOCK, THEN CHANGE IT - Enable Spell Indicators, choose a spell, then set Indicator Type."] = "SBLOCCA, POI CAMBIA - Abilita gli indicatori di incantesimo, scegli un incantesimo, quindi imposta il tipo di indicatore."
L["UNLOCK, THEN CHANGE IT - Enable the parent feature in this section first."] = "SBLOCCA, POI CAMBIA - Abilita prima la funzione genitore in questa sezione."
L["UNLOCK, THEN CHANGE IT - Turn on Spell Indicators in the earlier checkpoint; use Back if you skipped it."] = "SBLOCCA, POI CAMBIA - Attiva gli indicatori degli incantesimi nel checkpoint precedente; usa Indietro se lo hai saltato."
L["Unit frame status icons are on each unit page. Group Spell Indicators are in Group Frames > Auras; group status and corner indicators are in Group Frames > Status & Indicators."] = "Le icone di stato del frame dell'unità si trovano su ciascuna pagina dell'unità. Gli indicatori degli incantesimi di gruppo si trovano nei riquadri di gruppo > Aure; lo stato del gruppo e gli indicatori d'angolo si trovano in Riquadri gruppo > Stato e indicatori."
