L["Use Global Style > Bars for highlight borders and Group Frames > Status & Indicators for role, threat, dispel, corner, and raid-marker indicators. Spell Indicators are in Group Frames > Auras."] = "Utilizza Stile globale > Barre per evidenziare i bordi e cornici di gruppo > Stato e indicatori per indicatori di ruolo, minaccia, dissolvenza, angolo e indicatore di incursione. Gli indicatori degli incantesimi si trovano nei riquadri di gruppo > Aure."
