-- MSUF FULL CORE MENU SOURCE INVENTORY 2
-- Generated missing non-Assistant core keys for itIT.
L["+"] = "+"
L["Can Priority Frames automatically select healers, DPS, classes, or specs?"] = "I Priority Frames possono selezionare automaticamente guaritori, DPS, classi o specifiche?"
L["Can Priority Frames automatically show Augmentation Evokers?"] = "I Priority Frames possono mostrare automaticamente gli Evocatori di potenziamento?"
L["Can Priority Frames show my co-tank?"] = "I Priority Frames possono mostrare il mio co-tank?"
L["Can Priority Frames update during combat?"] = "I Priority Frames possono aggiornarsi durante il combattimento?"
L["Check that Priority Frames are enabled, you are grouped, and the matching base Party or Raid frames are enabled. Confirm that an assigned tank or manually pinned player is currently in the group and Visible slots is not full. Saved absent players create no empty placeholders, and protected roster changes made in combat finish after combat ends."] = "Controlla che i frame prioritari siano abilitati, che tu sia raggruppato e che i frame Party o Raid di base corrispondenti siano abilitati. Conferma che un carro armato assegnato o un giocatore bloccato manualmente sia attualmente nel gruppo e che gli slot visibili non siano pieni. I giocatori assenti salvati non creano segnaposti vuoti e le modifiche protette al roster apportate alla fine del combattimento al termine del combattimento."
L["Class Color and Health Gradient are runtime colors, not a single editable swatch."] = "Colore classe e Gradiente di salute sono colori di runtime, non un singolo campione modificabile."
L["Cleave Training Dummy"] = "Manichino da addestramento Cleave"
L["Custom 1-3 are always stored per frame. Icon styling and Full-Frame effects here only change "] = "Le personalizzazioni 1-3 vengono sempre memorizzate per frame. Lo stile delle icone e gli effetti full-frame qui cambiano solo"
L["Disabled or whitelist empty"] = "Disabilitato o whitelist vuota"
L["Do Priority Frame pins persist, and what order do they use?"] = "I pin del Priority Frame persistono e quale ordine utilizzano?"
L["Do Priority Frames inherit click casting and appearance?"] = "I frame prioritari ereditano la trasmissione e l'aspetto dei clic?"
L["Do Priority Frames use polling?"] = "I Priority Frames utilizzano il polling?"
L["Do Priority Frames work in parties and dungeons?"] = "I Priority Frames funzionano nei party e nei dungeon?"
L["Enter text"] = "Inserisci il testo"
L["Existing Priority frames remain usable in combat, but WoW protects secure group-frame membership and layout changes. Any pin, roster, slot, or placement change that needs a secure refresh is applied after combat ends. Change the Priority Frames keybinding out of combat."] = "I frame prioritari esistenti rimangono utilizzabili in combattimento, ma WoW protegge l'appartenenza sicura ai frame di gruppo e le modifiche al layout. Qualsiasi modifica a spilla, elenco, slot o posizionamento che richieda un aggiornamento sicuro viene applicata al termine del combattimento. Cambia la combinazione di tasti dei frame prioritari fuori dal combattimento."
L["Follows Unitframe Global Coloring. The swatch previews the current global bar color."] = "Segue la colorazione globale Unitframe. Il campione visualizza in anteprima il colore globale corrente della barra."
L["For Priority Frames, layout is profile-wide, while pins are character-specific. Visible slots can be set from one to five. Automatic tanks fill first, followed by manual pins in saved order; duplicate selections appear once. A saved player who is absent waits until that player rejoins the current group."] = "Per i frame prioritari, il layout è a livello di profilo, mentre i pin sono specifici del carattere. Gli slot visibili possono essere impostati da uno a cinque. Per prima cosa si riempiono automaticamente i serbatoi, seguiti dai perni manuali nell'ordine salvato; le selezioni duplicate vengono visualizzate una volta. Un giocatore salvato che è assente attende finché non si unisce al gruppo corrente."
L["Frames"] = "Cornici"
L["How do I pin or unpin a player in Priority Frames?"] = "Come faccio a bloccare o sbloccare un giocatore nei frame prioritari?"
L["How do I position Priority Frames?"] = "Come posso posizionare i Priority Frames?"
L["How should an Augmentation Evoker use Priority Frames?"] = "Come dovrebbe un Evocatore di Potenziamento usare i Priority Frames?"
L["Inherited: this scope follows Shared aura style. Enable custom aura style only when this scope needs different text, swipe, border, or timer settings."] = "Ereditato: questo ambito segue lo stile dell'aura condivisa. Abilita lo stile dell'aura personalizzato solo quando questo ambito richiede impostazioni diverse di testo, scorrimento, bordo o timer."
L["Leave text"] = "Lascia il testo"
L["Live "] = "Vivi"
L["Live preview is unavailable for this container. Sample mode remains available."] = "L'anteprima dal vivo non è disponibile per questo contenitore. La modalità campione rimane disponibile."
L["Live preview updates after combat. Sample mode remains available."] = "Aggiornamenti in anteprima dal vivo dopo il combattimento. La modalità campione rimane disponibile."
L["Manually pin the teammates you want to keep visible for monitoring or click-casting. Priority Frames does not decide who should receive Prescience or Ebon Might. Configure Group Frames > Auras > Spell Indicators if you want inherited Priority frames to show Prescience, Ebon Might, Shifting Sands, Blistering Scales, or other configured effects."] = "Blocca manualmente i compagni di squadra che desideri mantenere visibili per il monitoraggio o il clickcasting. Priority Frames non decide chi dovrebbe ricevere Prescience o Ebon Might. Configura i frame di gruppo > Aure > Indicatori degli incantesimi se desideri che i frame di priorità ereditati mostrino Prescienza, Potenza d'ebano, Sabbie mobili, Scaglie vesciche o altri effetti configurati."
L["Mouseover highlight"] = "Evidenziazione al passaggio del mouse"
L["Native · "] = "Nativo ·"
L["No continuous polling ticker or OnUpdate loop is used for Priority selection. It resolves the roster when configuration, pins, group state, or relevant unit identity changes require a refresh. Automatic selection reads WoW's assigned TANK role and does not inspect every group member's specialization in the background."] = "Per la selezione della priorità non viene utilizzato alcun ticker di polling continuo o ciclo OnUpdate. Risolve il roster quando la configurazione, i pin, lo stato del gruppo o le modifiche relative all'identità dell'unità rilevante richiedono un aggiornamento. La selezione automatica legge il ruolo TANK assegnato a WoW e non controlla in background la specializzazione di ogni membro del gruppo."
L["No live "] = "Niente dal vivo"
L["No live member"] = "Nessun membro dal vivo"
L["No matching aura active"] = "Nessuna aura corrispondente attiva"
L["No. Automatic selection currently uses only WoW's assigned TANK role. Healers, DPS, classes, specializations, and support targets must be pinned manually with the hover hotkey. This avoids background inspection or polling and keeps the selection deterministic."] = "No. La selezione automatica attualmente utilizza solo il ruolo TANK assegnato da WoW. Guaritori, DPS, classi, specializzazioni e obiettivi di supporto devono essere bloccati manualmente con il tasto di scelta rapida al passaggio del mouse. Ciò evita l'ispezione in background o il polling e mantiene la selezione deterministica."
L["Open Group Frames > Priority > Placement. Attach the strip to the right, left, top, or bottom of the active Party/Raid container, or choose Free position and use the dedicated Priority Frames mover in Edit Mode. The same page controls growth, spacing, attachment gap, and alignment offset."] = "Apri Raggruppa frame > Priorità > Posizionamento. Attacca la striscia a destra, a sinistra, in alto o in basso del contenitore Party/Raid attivo, oppure scegli Posizione libera e utilizza lo spostamento dei frame di priorità dedicato in modalità Modifica. La stessa pagina controlla la crescita, la spaziatura, lo spazio tra gli allegati e l'offset dell'allineamento."
L["Override active: this scope keeps its own aura style. Shared style changes will not replace it until the override is reset."] = "Override attivo: questo mirino mantiene il proprio stile di aura. Le modifiche allo stile condiviso non lo sostituiranno finché la sostituzione non verrà reimpostata."
L["Priority Frames does not automatically detect other players' specializations. Automatic selection currently supports WoW-assigned tanks only. Pin an Augmentation Evoker manually with the hover hotkey; Priority Frames does not choose ideal Prescience or Ebon Might targets."] = "Priority Frames non rileva automaticamente le specializzazioni degli altri giocatori. La selezione automatica attualmente supporta solo i carri armati assegnati da WoW. Blocca manualmente un Evocatore di Potenziamento con il tasto di scelta rapida al passaggio del mouse; Priority Frames non sceglie bersagli ideali di Prescience o Ebon Might."
L["Priority Frames duplicate automatic tanks and manually pinned current group members into a stable extra strip without removing them from the normal Party or Raid frames. In a party they inherit Party Frames; in a raid they inherit the active Raid or Mythic Raid frames. They work in parties, raids, and Mythic raids, inherit the active group-frame click-cast behavior, and require the matching base group frames to be enabled."] = "I frame prioritari duplicano i carri armati automatici e bloccano manualmente i membri attuali del gruppo in una striscia extra stabile senza rimuoverli dai normali frame Party o Raid. In un party ereditano i Party Frames; in un raid ereditano i frame Raid o Raid Mitico attivi. Funzionano in gruppi, raid e raid mitici, ereditano il comportamento di clic-cast del frame di gruppo attivo e richiedono che i frame del gruppo base corrispondente siano abilitati."
L["Shared aura style is the baseline for unit-frame aura text, swipe, border, and timer settings. Party and Raid are group-frame style scopes with their own settings."] = "Lo stile dell'aura condivisa è la base per le impostazioni del testo dell'aura, dello scorrimento, del bordo e del timer del frame unitario. Party e Raid sono ambiti in stile frame di gruppo con le proprie impostazioni."
L["Textures are shared except Party/Raid group-frame overrides. Gradients can be customized per unit or group scope."] = "Le texture sono condivise eccetto le sostituzioni dei frame di gruppo Party/Raid. I gradienti possono essere personalizzati per unità o ambito di gruppo."
L["This group scope can use custom textures and gradients. Raid also applies to Mythic Raid."] = "Questo ambito di gruppo può utilizzare trame e gradienti personalizzati. Il Raid si applica anche al Raid Mitico."
L["This scope can use custom gradients and bar settings. Textures still follow Shared."] = "Questo ambito può utilizzare gradienti personalizzati e impostazioni della barra. Le texture seguono ancora Shared."
L["This scope follows Shared bar settings. Turn on custom settings here when this scope needs different gradients or bar settings."] = "Questo ambito segue le impostazioni della barra condivisa. Attiva qui le impostazioni personalizzate quando questo ambito necessita di gradienti o impostazioni della barra diversi."
L["Updates after combat"] = "Aggiornamenti dopo il combattimento"
L["Where can I request a Priority Frames feature?"] = "Dove posso richiedere la funzionalità Priority Frames?"
L["While grouped, set the hover hotkey on Group Frames > Priority. Hover an MSUF Party, Raid, or Priority frame and press the Priority Frames hotkey to pin or unpin that player. Players cannot be added by typing a name or while outside the current group; a saved absent pin waits and reappears when that player rejoins."] = "Mentre sei raggruppato, imposta il tasto di scelta rapida al passaggio del mouse su Raggruppa frame > Priorità. Passa il mouse su un frame Party, Raid o Priorità MSUF e premi il tasto di scelta rapida Frame prioritari per bloccare o sbloccare quel giocatore. I giocatori non possono essere aggiunti digitando un nome o mentre sono fuori dal gruppo corrente; un segnaposto assente salvato attende e riappare quando quel giocatore si ricongiunge."
L["Why are my Priority Frames empty or missing?"] = "Perché i miei Priority Frame sono vuoti o mancanti?"
L["Yes. Include tanks automatically selects current group members whose WoW-assigned role is TANK, normally including both you and your co-tank. To show only your co-tank, disable automatic tanks and manually pin the other tank. If WoW has not assigned that player the TANK role, manual pinning is the fallback."] = "Sì. Includi carri armati seleziona automaticamente i membri attuali del gruppo il cui ruolo assegnato da WoW è TANK, normalmente includendo sia te che il tuo co-tank. Per mostrare solo il tuo co-tank, disabilita i serbatoi automatici e blocca manualmente l'altro serbatoio. Se WoW non ha assegnato a quel giocatore il ruolo TANK, il blocco manuale è il fallback."
L["Yes. Priority Frames inherit the active Party, Raid, or Mythic Raid frame appearance, including configured bars, text, auras, status indicators, and spell indicators. They use the same MSUF click-casting registration and unit behavior, so existing click-cast bindings also work on the duplicated frames."] = "Sì. I frame prioritari ereditano l'aspetto del frame attivo del Party, del Raid o del Raid Mitico, comprese le barre configurate, il testo, le aure, gli indicatori di stato e gli indicatori di incantesimo. Utilizzano la stessa registrazione di clic-cast MSUF e il comportamento dell'unità, quindi i collegamenti di clic-cast esistenti funzionano anche sui fotogrammi duplicati."
L["Yes. Priority Frames work in parties, raids, and Mythic raids. In a party or dungeon they inherit Party Frames; in a raid they inherit the active Raid or Mythic Raid setup. They do not create a solo strip, and the matching base Party or Raid frames must be enabled."] = "Sì. I frame di priorità funzionano nei gruppi, nei raid e nei raid mitici. In un party o in un dungeon ereditano i Party Frames; in un raid ereditano la configurazione Raid attiva o Raid Mitico. Non creano una striscia solista e i frame Party o Raid base corrispondenti devono essere abilitati."
