L["Art for every unit's power bar. Leave on Use bar texture to keep the shared bar art. Each unit page can override this, and the Class Resources detached power texture still wins for a detached Player bar."] = "Grafica per la barra della risorsa di ogni unità. Lascia su «Usa texture barra» per mantenere la grafica condivisa. Ogni pagina unità può sovrascriverla, e la texture separata delle Risorse di classe ha comunque la priorità per una barra del giocatore separata."
L["Art for this frame's power bar, detached or not. Leave on the global option to follow the shared Bars power texture."] = "Grafica per la barra della risorsa di questo riquadro, separata o meno. Lascia sull'opzione globale per seguire la texture condivisa delle Barre."
L["Axis and direction the Health and Power bars fill. Vertical options fill bottom-to-top or top-to-bottom; combines with Smooth fill."] = "Asse e direzione di riempimento delle barre di salute e risorsa. Le opzioni verticali riempiono dal basso verso l'alto o dall'alto verso il basso e si combinano con il riempimento morbido."
L["Background art behind every unit's power bar. Overridable per unit on the unit page."] = "Grafica di sfondo dietro la barra della risorsa di ogni unità. Sovrascrivibile per unità nella sua pagina."
L["Background art behind this frame's power bar."] = "Grafica di sfondo dietro la barra della risorsa di questo riquadro."

